/* 390px ELI5 长卷骨架（三套主题共用尺寸；颜色在 theme-*-long.css） */
* { box-sizing: border-box; margin: 0; padding: 0; }
html, body {
  width: 390px;
  margin: 0;
  padding: 0;
  overflow: visible;
  -webkit-font-smoothing: antialiased;
}
.phone {
  position: relative;
  width: 390px;
  margin: 0;
  padding: 22px 16px 28px;
  overflow: hidden;
}
.atm, .mesh, .noise, .wm {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
.atm { z-index: 0; }
.mesh { z-index: 0; }
.noise { z-index: 2; }
.wm {
  z-index: 20;
  overflow: hidden;
  background-repeat: repeat;
  background-size: 300px 188px;
}
.content { position: relative; z-index: 3; }
.ui-title { font-family: 'Noto Serif SC','Source Han Serif SC','Songti SC','SimSun',serif; font-weight: 900; }
.wenkai { font-family: 'LXGW WenKai','霞鹜文楷','Microsoft YaHei',serif; }
.ui-bold { font-family: 'HarmonyOS_Sans_SC_Bold','HarmonyOS Sans SC','Microsoft YaHei',sans-serif; font-weight: 700; }

.eli5-head { position: relative; margin-bottom: 18px; }
.wm-num {
  position: absolute; right: -6px; top: -18px; z-index: 0;
  font-size: 92px; line-height: .85; opacity: .1;
  pointer-events: none; letter-spacing: -0.06em;
}
.head-row { display: flex; align-items: center; gap: 10px; position: relative; z-index: 1; }
.idx-sq {
  width: 36px; height: 36px; border-radius: 10px;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 15px; flex-shrink: 0;
}
.c-en { font-size: 11px; letter-spacing: .22em; }
.c-cn { font-size: 13px; margin-top: 1px; font-family: 'LXGW WenKai','霞鹜文楷',serif; }
h1.ui-title { font-size: 26px; line-height: 1.22; letter-spacing: -0.02em; margin: 12px 0 8px; position: relative; z-index: 1; }
.tagline { font-size: 14px; line-height: 1.55; margin-bottom: 4px; }
section { margin-top: 22px; }
h2 {
  font-size: 16px; line-height: 1.3;
  display: flex; align-items: center; gap: 8px;
  margin-bottom: 10px;
}
.num, .dot-n {
  width: 24px; height: 24px; border-radius: 9999px;
  display: inline-flex; align-items: center; justify-content: center;
  color: #fff; font-size: 12px; font-weight: 700; flex-shrink: 0;
}
.card-paper, .card-blush, .card-sage, .card-callout, .card-principle, .tier, .hl-bar {
  border-radius: 14px;
  padding: 12px 14px;
  margin-bottom: 8px;
}
.card-principle { border: 1.5px dashed; }
.big { font-size: 15px; font-weight: 700; margin-bottom: 4px; }
.muted { font-size: 13.5px; line-height: 1.55; }
p + p { margin-top: 6px; }
.story { display: flex; gap: 10px; align-items: flex-start; }
.emoji { font-size: 28px; line-height: 1; flex-shrink: 0; width: 36px; text-align: center; padding-top: 2px; }
.story .body { min-width: 0; flex: 1; }
.flow { display: flex; flex-direction: column; gap: 6px; margin: 4px 0 10px; }
.box {
  border-radius: 12px; padding: 10px 12px; font-weight: 700; font-size: 14px;
  text-align: center; border: 2px solid;
}
.box .sub { display: block; margin-top: 3px; font-weight: 500; font-size: 12.5px; }
.arrow { text-align: center; font-size: 12px; font-weight: 700; opacity: .7; }
.pill {
  display: inline-block; padding: 2px 9px; border-radius: 999px;
  font-size: 11.5px; font-weight: 700; margin-bottom: 6px;
}
.brick { display: flex; flex-direction: column; gap: 8px; }
.brick .item { border-radius: 12px; padding: 11px 12px; }
.brick .name { font-weight: 700; margin-bottom: 3px; font-size: 14px; }
.brick .desc { font-size: 13.5px; line-height: 1.5; }
.pair { display: flex; flex-direction: column; gap: 8px; }
.pair-row { display: flex; gap: 8px; align-items: flex-start; }
.x-mark, .ok-mark {
  width: 22px; height: 22px; border-radius: 9999px;
  display: flex; align-items: center; justify-content: center;
  color: #fff; font-size: 12px; flex-shrink: 0; margin-top: 2px;
}
.tier { display: flex; align-items: stretch; padding: 0; overflow: hidden; }
.tier-lab {
  color: #fff; display: flex; flex-direction: column; justify-content: center;
  padding: 10px 12px; min-width: 72px; font-size: 13px; line-height: 1.2;
}
.tier-body { padding: 10px 12px; flex: 1; min-width: 0; }
.hl-bar { border-left: 6px solid; }
.hero-orb {
  width: 88px; height: 88px; border-radius: 9999px;
  display: flex; align-items: center; justify-content: center;
  color: #fff; position: relative; flex-shrink: 0;
  font-size: 40px; line-height: 1;
}
.hero-orb::after {
  content: ''; position: absolute; inset: -8px; border-radius: 9999px;
  border: 1.5px dashed;
}
.hero-row { display: flex; align-items: center; gap: 12px; margin: 8px 0 12px; }
.pill-dark {
  border-radius: 9999px; padding: 10px 14px;
  display: flex; align-items: center; gap: 8px; font-size: 13.5px; line-height: 1.4;
}
.takeaways { list-style: none; counter-reset: t; }
.takeaways li {
  counter-increment: t; position: relative;
  padding-left: 26px; margin: 8px 0; font-size: 14px; line-height: 1.5;
}
.takeaways li::before {
  content: counter(t); position: absolute; left: 0; top: 1px;
  width: 18px; height: 18px; border-radius: 50%;
  font-size: 11px; font-weight: 700;
  display: flex; align-items: center; justify-content: center;
}
.c-foot {
  display: flex; justify-content: space-between; align-items: center;
  padding-top: 10px; margin-top: 8px; font-size: 11px;
}
.c-foot-sq {
  width: 8px; height: 8px; border-radius: 2px;
  display: inline-block; margin-right: 6px; vertical-align: middle;
}
.credit {
  margin-top: 16px; padding-top: 12px;
  text-align: center; font-size: 11px; font-weight: 600; line-height: 1.5;
}
.credit .copy { margin-top: 3px; font-weight: 500; font-size: 10.5px; }
.shift { width: 94%; margin-left: auto; }

